  /* ── التصدير: لا يعتمد على ترتيب قراءة الملفات ──
     figs.js قد يُقرأ قبل هذا الملف أو بعده فيَعُدّل الخاصية، فنجعل الخاصية
     نفسها تُرجع اتحاد ما قبل وما بعده، فلا يضيع رسمٌ من الرسمين. */
  let baseF = window.FIGS || {};
  let baseS = window.FIG_SUBJ || {};
  const uni = (a, b) => Object.assign(Object.assign({}, a || {}), b);
  Object.defineProperty(window, 'FIGS', {
    configurable: true, enumerable: true,
    get: () => uni(baseF, FIGS),
    set: v => { baseF = v || {}; }
  });
